-- UNA-Migration-Min-System-Version: 15.0.0-RC4
-- The default email header shows the logo uploaded in Designer ({site_logo}: the dark-mode logo in dark mode, the site title when there is none) instead of the site title.
-- The default header and footer get dark-mode colours and a darker grey for the title and footer text, which reach 3:1 and 4.5:1.
-- Untouched defaults are replaced whole; a customised header that kept the default title line gets the logo there.
UPDATE `sys_options` SET `value` = '<html>\r\n    <head>\r\n        <meta name="color-scheme" content="light dark">\r\n        <meta name="supported-color-schemes" content="light dark">\r\n        <style>\r\n            :root { color-scheme: light dark; supported-color-schemes: light dark; }\r\n            @media (prefers-color-scheme: dark) {\r\n                .bx-email-bg { background-color:#18181b !important; }\r\n                .bx-email-text { color:#e4e4e7 !important; }\r\n                .bx-email-muted { color:#a1a1aa !important; }\r\n                .bx-email-line { border-color:#3f3f46 !important; }\r\n                .bx-email-bg a { color:#8ab4f8 !important; }\r\n                .bx-email-logo-light { display:none !important; }\r\n                .bx-email-logo-dark { display:block !important; max-height:none !important; overflow:visible !important; }\r\n            }\r\n        </style>\r\n    </head>\r\n    <body bgcolor="#fff" class="bx-email-bg" style="margin:0; padding:0;">\r\n        <div class="bx-email-bg" style="background-color:#fff;">\r\n            <table width="100%" border="0" cellspacing="0" cellpadding="0" align="center">\r\n                <tr><td valign="top">\r\n                    <div class="bx-email-text" style="color:#333; padding:20px; font:14px Helvetica, Arial, sans-serif;">\r\n                        <div class="bx-email-line bx-email-muted" style="border-bottom:2px solid #eee; padding-bottom:10px; margin-bottom:20px; font-weight:bold; font-size:22px; color:#666;">{site_logo}</div>' WHERE `name` = 'site_email_html_template_header' AND REPLACE(`value`, '\r', '') = '<html>\n    <head></head>\n    <body bgcolor="#fff" style="margin:0; padding:0;">\n        <div style="background-color:#fff;">\n            <table width="100%" border="0" cellspacing="0" cellpadding="0" align="center">\n                <tr><td valign="top">\n                    <div style="color:#333; padding:20px; font:14px Helvetica, Arial, sans-serif;">\n                        <div style="border-bottom:2px solid #eee; padding-bottom:10px; margin-bottom:20px; font-weight:bold; font-size:22px; color:#999;">{site_name}</div>';
UPDATE `sys_options` SET `value` = '\r\n                    </div>\r\n                </td></tr>\r\n                <tr><td valign="top">\r\n                    <div class="bx-email-muted" style="color:#666; padding:0 20px 20px 20px; font:11px Helvetica, Arial, sans-serif;">\r\n                        <div class="bx-email-line" style="border-top:2px solid #eee; padding-top:10px;">{about_us}&nbsp;&nbsp;&nbsp;{unsubscribe}</div>\r\n                    </div>\r\n                </td></tr>\r\n            </table>\r\n        </div>\r\n    </body>\r\n</html>' WHERE `name` = 'site_email_html_template_footer' AND REPLACE(`value`, '\r', '') = '\n                    </div>\n                </td></tr>\n                <tr><td valign="top">\n                    <div style="color:#999; padding:0 20px 20px 20px; font:11px Helvetica, Arial, sans-serif;">\n                        <div style="border-top:2px solid #eee; padding-top:10px;">{about_us}&nbsp;&nbsp;&nbsp;{unsubscribe}</div>\n                    </div>\n                </td></tr>\n            </table>\n        </div>\n    </body>\n</html>';
UPDATE `sys_options` SET `value` = REPLACE(`value`, 'font-weight:bold; font-size:22px; color:#999;">{site_name}</div>', 'font-weight:bold; font-size:22px; color:#666;">{site_logo}</div>') WHERE `name` = 'site_email_html_template_header' AND `value` LIKE '%font-weight:bold; font-size:22px; color:#999;">{site_name}</div>%';
